mapper.select:
SELECT
FROM finance_recurring r LEFT JOIN finance_category c ON c.id = r.category_id AND c.deleted = 0 AND c.user_id = r.user_id LEFT JOIN finance_account a ON a.id = r.account_id AND a.deleted = 0 AND a.user_id = r.user_id LEFT JOIN finance_account fa ON fa.id = r.from_account_id AND fa.deleted = 0 AND fa.user_id = r.user_id LEFT JOIN finance_account ta ON ta.id = r.to_account_id AND ta.deleted = 0 AND ta.user_id = r.user_id
r.deleted = 0 AND r.user_id = #{userId}
AND r.name LIKE CONCAT('%', #{dto.name}, '%')
AND r.direction = #{dto.direction}
AND r.enabled = #{dto.enabled}
ORDER BY r.sort_order ASC, r.id DESC
